// Generate a Scenario Outline that runs the 02 onboarding-to-dashboard flow N
// times, one Examples row per iteration, reusing the existing step definitions.
//
// Written OUTSIDE ./features (default: test-artifacts/perf) so the normal spec
// glob never picks it up; the perf CI job passes --spec to the generated file.
//
// Usage: node utils/gen-stress-feature.mjs [count] [outPath]

import { writeFileSync, mkdirSync } from "fs";
import { dirname } from "path";

const count = Math.max(1, parseInt(process.argv[2] || "50", 10));
const out = process.argv[3] || "test-artifacts/perf/02_signup_stress.feature";

const rows = Array.from({ length: count }, (_, i) => `      | ${i + 1} |`).join(
  "\n",
);

const feature = `Feature: 02 signup stress and performance baseline

  # Generated by utils/gen-stress-feature.mjs (count=${count}). Each row runs the
  # full offline onboarding to the dashboard; per-iteration metrics are collected
  # by utils/perf.ts when E2E_PERF=1.
  Scenario Outline: Onboarding to dashboard iteration <i>
    Given the app is launched fresh
    When I tap "ENGLISH"
    And I tap the right arrow
    Then I should see "Privacy Policy"
    When I accept the privacy policy
    Then I should see "PHONE"
    When I enter phone number "1234567890"
    And I tap the right arrow
    Then I should see "First Name"
    When I enter name "Test" "User"
    And I tap the right arrow
    Then I should reach the dashboard

    Examples:
      | i |
${rows}
`;

mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, feature);
console.log(`[gen-stress] wrote ${count}-iteration outline to ${out}`);
